const $=id=>document.getElementById(id);let token='',page=1,epoch=0;const notice=s=>$('notice').textContent=s;
async function api(path='',options={}){const r=await fetch('/api/admin/notifications'+path,{...options,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'}});const d=await r.json();if(!r.ok)throw Error(d.error);return d}
async function load(){const n=++epoch;const d=await api('?'+new URLSearchParams({page,state:$('state').value}));if(n!==epoch||!token)return;$('summary').textContent=d.unread+' notification(s) active(s) non lue(s)';$('rows').replaceChildren();for(const x of d.items){const tr=document.createElement('tr');for(const v of [x.priority,x.kind,x.label,x.due,x.details,(x.active?'Active':'Résolue')+' / '+(x.read_at?'Lue':'Non lue')]){const td=document.createElement('td');td.textContent=v;tr.append(td)}const td=document.createElement('td');if(!x.read_at){const b=document.createElement('button');b.textContent='Marquer comme lue';b.onclick=async()=>{try{await api('',{method:'POST',body:JSON.stringify({id:x.id})});if(token){page=1;await load()}}catch(e){notice(e.message)}};td.append(b)}tr.append(td);$('rows').append(tr)}$('pages').textContent='Page '+page+' · '+d.total+' notification(s)';$('prev').disabled=page===1;$('next').disabled=page*25>=d.total}
async function refresh(){try{await load()}catch(e){notice(e.message)}}
$('login-form').onsubmit=async e=>{e.preventDefault();token=$('token').value;$('token').value='';page=1;try{await load();$('login').hidden=true;$('workspace').hidden=false;notice('Connecté.')}catch(e){token='';notice(e.message)}};
$('logout').onclick=()=>{epoch++;token='';$('rows').replaceChildren();$('summary').textContent='';$('pages').textContent='';$('workspace').hidden=true;$('login').hidden=false;notice('Déconnecté.')};$('filter').onsubmit=e=>{e.preventDefault();page=1;refresh()};$('prev').onclick=()=>{if(page>1){page--;refresh()}};$('next').onclick=()=>{page++;refresh()};
